  function isPhone() { return window.matchMedia ? window.matchMedia('(max-width: 899px)').matches : window.innerWidth < 900; }
  function finePointer() { return window.matchMedia ? window.matchMedia('(pointer: fine)').matches : true; }
  function boardDate() { return E.isDate(ui.board) ? ui.board : TODAY; }
  function dayJobs(d) { return db.jobs.filter(function (j) { return j.date === d && E.isBooked(j); }); }
  function queueJobs() {
    var rank = function (j) { return j.status === 'parts' ? 3 : j.priority === 'emergency' ? 0 : ['risk', 'overdue'].indexOf(slaOf(j).state) >= 0 ? 1 : 2; };
    return db.jobs.filter(function (j) { return j.status === 'new' || j.status === 'parts'; }).sort(function (a, b) {
      var sa = slaOf(a).due || '9999', sb = slaOf(b).due || '9999';
      return rank(a) - rank(b) || (sa < sb ? -1 : sa > sb ? 1 : 0) || ((a.preferredDate || '9999') < (b.preferredDate || '9999') ? -1 : 1) || (a.reportedAt < b.reportedAt ? -1 : 1);
    });
  }
  PAGES.board = function () {
    pageTitle = 'Dispatch board';
    var d = boardDate(), techs = activeTechs(), jobs = dayJobs(d), queue = queueJobs();
    var nNew = queue.filter(function (j) { return j.status === 'new'; }).length, nEm = queue.filter(function (j) { return j.status === 'new' && j.priority === 'emergency'; }).length;
    var risk = db.jobs.filter(function (j) { return E.isOpen(j.status) && (slaOf(j).state === 'risk' || slaOf(j).state === 'overdue'); }).length;
    var parts = queue.filter(function (j) { return j.status === 'parts'; }).length, toInv = db.jobs.filter(function (j) { return j.status === 'done'; }).length;
    try { if (window.StratumShell && StratumShell.needs) StratumShell.needs('service', [nNew && { text: nEm ? 'Jobs not planned, with an emergency' : 'Jobs not planned', count: nNew, href: '/service/#/board', tone: nEm ? 'bad' : 'warn' }, risk && { text: 'Jobs with the SLA at risk', count: risk, href: '/service/#/jobs', tone: 'warn' }, toInv && { text: 'Done jobs to invoice', count: toInv, href: '/service/#/invoicing', tone: 'info' }].filter(Boolean)); } catch (e) {}
    var booked = 0; jobs.forEach(function (j) { var r = E.winRange(j); booked += r[1] - r[0]; });
    var h = head(eyebrowText('Dispatch board · ' + esc(dayName(d)) + ' · ' + esc(dt(d))), 'Who goes where', esc(plural(jobs.length, 'job', 'jobs') + ' on ' + dtw(d) + ' · ' + plural(techs.length, 'technician', 'technicians')) + (HMAP[d] ? ' · ' + esc(HMAP[d]) + ' (public holiday)' : ''),
      '<button type="button" class="btn pri" data-act="newjob">' + ic('plus') + 'New job</button>');
    h += staleNotice();
    h += '<div class="kpis">' + kpi('Not planned', nf0.format(nNew), nEm ? plural(nEm, 'emergency', 'emergencies') + ' waiting' : 'none urgent', nEm ? 'bad' : nNew ? '' : 'good') +
      kpi('SLA at risk', nf0.format(risk), 'arrival due within 4 h or overdue', risk ? 'warn' : 'good', '#/jobs') +
      kpi('Waiting for parts', nf0.format(parts), 'book when the part is in', parts ? 'warn' : '') +
      kpi('Booked windows', booked + ' of ' + techs.length * 4, 'on ' + dtw(d), '') +
      kpi('Done, to invoice', nf0.format(toInv), 'go to invoicing', '', '#/invoicing') + '</div>';
    h += dayBar(d) + weekStrip(d) + selBar();
    h += isPhone() ? phoneBoard(d, techs, jobs, queue) : '<div class="boardwrap">' + gridBoard(d, techs, jobs) + queuePanel(queue) + '</div>';
    h += '<p class="hint" style="margin-top:12px">Windows are arrival windows. Select a card and then <b>Assign here</b>, drag a card onto a window, or use <b>Assign…</b>. Warnings: busy (double-booked), skill, far (over ' + esc(db.settings.farKm) + ' km from the technician\'s base), after SLA.</p>';
    return h;
  };
  function dayBar(d) {
    return '<div class="daybar no-print"><button type="button" class="btn icon" data-act="bday" data-v="-1" aria-label="Previous working day">' + ic('back') + '</button>' +
      '<input type="date" class="datein" id="boardDate" value="' + esc(d) + '" aria-label="Board date">' +
      '<button type="button" class="btn icon" data-act="bday" data-v="1" aria-label="Next working day">' + ic('fwd') + '</button>' +
      (d !== TODAY ? '<button type="button" class="btn sm" data-act="bday" data-v="0">Today</button>' : '') + '</div>';
  }
  function weekStrip(d) {
    var mon = E.mondayOf(d), out = [];
    for (var i = 0; i < 7; i++) {
      var x = E.addDays(mon, i), n = dayJobs(x).length, off = !E.isWorkday(x, HMAP);
      if (i >= 5 && !n && x !== d) continue;
      out.push('<button type="button" class="' + (off ? 'off' : '') + '" data-act="bset" data-v="' + x + '" aria-pressed="' + (x === d) + '"><b>' + esc(WD[E.dow(x)] + ' ' + dts(x)) + '</b><small>' + esc(HMAP[x] ? HMAP[x] : n ? plural(n, 'job', 'jobs') : 'free') + (x === TODAY ? ' · today' : '') + '</small></button>');
    }
    return '<div class="wk" role="group" aria-label="Days of the week">' + out.join('') + '</div>';
  }
  function selBar() {
    var j = sel && IX.job[sel]; if (!j) return '';
    return '<div class="selbar" role="status"><span><b>' + esc(j.no) + '</b> · ' + esc(custOf(j).name + ' · ' + custOf(j).city + ' · ' + typeName(j.type)) + '. Choose a free window, or press Esc.</span><span class="btns">' +
      '<button type="button" class="btn sm" data-act="assign" data-v="' + esc(j.id) + '">Assign…</button><a class="btn sm" href="#/jobs/' + esc(j.id) + '">Open</a>' +
      (j.status === 'scheduled' ? '<button type="button" class="btn sm" data-act="unassign" data-v="' + esc(j.id) + '">To the queue</button>' : '') + '<button type="button" class="btn sm" data-act="unsel">Cancel</button></span></div>';
  }
  function cardLine(j, inQueue) {
    var st = j.status;
    if (inQueue) return st === 'parts' ? 'waiting for parts' : j.preferredDate ? 'wants ' + dts(j.preferredDate) : 'reported ' + dtm(j.reportedAt);
    return st === 'onsite' ? 'since ' + tm(j.arriveAt) : st === 'travelling' ? 'left ' + tm(j.travelAt) : E.isDone(j) ? '✓ ' + tm(j.finishAt) : E.jobSpan(j) > 1 ? winLabel(j) : '';
  }
  function boardCard(j, inQueue) {
    var c = custOf(j), t = techOf(j), a = assetOf(j), st = j.status, drag = canPlan(j) && !isPhone() && finePointer();
    return '<button type="button" class="jc tc tc-' + esc(t ? t.colour : 'c8') + (j.priority === 'emergency' ? ' emergency' : '') + ' st-' + esc(st) + '-c" data-act="pick" data-v="' + esc(j.id) + '" data-fid="jc-' + esc(j.id) + '" aria-pressed="' + (sel === j.id) + '"' + (drag ? ' draggable="true"' : '') +
      ' aria-label="' + esc(j.no + ', ' + c.name + ', ' + c.city + ', ' + typeName(j.type) + ', ' + E.STATUS[st].name + (canPlan(j) ? '. Select to plan.' : '. Open.')) + '">' +
      '<span class="l1"><span>' + esc(j.no) + '</span><span>' + esc(cardLine(j, inQueue)) + '</span></span><span class="l2">' + esc(c.name) + '</span><span class="l3">' + esc(c.city + ' · ' + typeName(j.type) + ' · ' + kindShort(a.kind)) + '</span>' +
      '<span class="badges">' + prBadge(j) + slaBadge(j, true) + (st === 'travelling' || st === 'onsite' || st === 'parts' ? stBadge(j) : '') + '</span></button>';
  }
  function dropBtn(j, t, d, win) {
    var list = E.conflicts(j, { date: d, window: win }, conflictCtx(j, t.id)), err = list.filter(function (x) { return x.level === 'error'; });
    var short = { double: 'busy', skill: 'skill', far: 'far', dayoff: 'day off', sla: 'after SLA', past: 'past', span: 'no room' };
    var label = 'Assign ' + j.no + ' to ' + t.name + ', ' + winLabelFor(j, win) + (list.length ? '. Warnings: ' + list.map(function (x) { return x.text; }).join(' ') : '. No conflicts.');
    return '<button type="button" class="drop' + (err.length ? ' blocked' : list.length ? ' warn' : '') + '" data-act="drop" data-cell="' + esc(t.id + '|' + d + '|' + win) + '" data-fid="drop-' + esc(t.id + '-' + win) + '"' + (err.length ? ' disabled' : '') + ' aria-label="' + esc(label) + '" title="' + esc(list.map(function (x) { return x.text; }).join('\n') || 'No conflicts') + '">' +
      '<span>' + (err.length ? 'No room' : 'Assign here') + '</span><span class="hints">' + (list.length ? list.map(function (x) { return '<span>' + esc(short[x.code] || x.code) + '</span>'; }).join('') : '<span class="ok">fits</span>') + '</span></button>';
  }
  function gridBoard(d, techs, jobs) {
    var sj = sel && IX.job[sel] && canPlan(IX.job[sel]) ? IX.job[sel] : null, now = nowLj();
    var h = '<section class="card"><div class="tw"><div class="bgrid" role="table" aria-label="Dispatch board for ' + esc(dt(d)) + '"><div class="bh" role="columnheader">Technician</div>' + E.WINDOWS.map(function (w) { return '<div class="bh" role="columnheader">' + w.label + '</div>'; }).join('');
    techs.forEach(function (t) {
      var mine = jobs.filter(function (j) { return j.techId === t.id; }), occ = {};
      mine.forEach(function (j) { var r = E.winRange(j); for (var w = r[0]; w < r[1]; w++) occ[w] = 1; });
      h += '<div class="bt tc tc-' + esc(t.colour) + '" role="rowheader"><div class="nm"><span class="tdot" aria-hidden="true"></span><span>' + esc(t.name) + '</span></div><small>' + esc(t.base) + ' · ' + Object.keys(occ).length + ' of 4 booked</small><div class="skills">' + skillTags(t) + '</div></div>';
      for (var w = 0; w < 4; w++) {
        var starts = mine.filter(function (j) { return E.winIndex(j.window) === w; }), cont = mine.filter(function (j) { var r = E.winRange(j); return r[0] < w && w < r[1]; }), span = 1;
        if (starts.length === 1 && !cont.length) {
          var s = E.jobSpan(starts[0]), clear = true;
          for (var k = w + 1; k < Math.min(4, w + s); k++) if (mine.some(function (j) { var r = E.winRange(j); return j !== starts[0] && r[0] <= k && k < r[1]; })) clear = false;
          if (clear) span = Math.min(4 - w, s);
        }
        var endW = E.WINDOWS[Math.min(3, w + span - 1)], past = E.stamp(d, endW.end) <= now;
        h += '<div class="bc' + (past ? ' past' : '') + '" role="cell" data-cell="' + esc(t.id + '|' + d + '|' + E.WINDOWS[w].id) + '"' + (span > 1 ? ' style="grid-column:span ' + span + '"' : '') + '>' +
          starts.map(function (j) { return boardCard(j); }).join('') + cont.map(function (j) { return '<span class="hint">↳ ' + esc(j.no) + ' continues</span>'; }).join('');
        if (sj) h += dropBtn(sj, t, d, E.WINDOWS[w].id);
        else if (!starts.length && !cont.length) h += '<span class="free">' + (past ? '' : 'Free') + '</span>';
        h += '</div>';
        w += span - 1;
      }
    });
    return h + '</div></div></section>';
  }
  function qItem(j) {
    return '<div class="qitem">' + boardCard(j, true) + (j.status === 'parts' && j.partsNote ? '<span class="hint">' + esc(j.partsNote) + '</span>' : '') +
      '<div class="btns"><button type="button" class="btn sm" data-act="assign" data-v="' + esc(j.id) + '" data-fid="as-' + esc(j.id) + '">Assign…</button><a class="btn sm ghost" href="#/jobs/' + esc(j.id) + '">Open</a></div></div>';
  }
  function queuePanel(queue) {
    var groups = [['Emergencies', queue.filter(function (j) { return j.status === 'new' && j.priority === 'emergency'; })], ['New', queue.filter(function (j) { return j.status === 'new' && j.priority !== 'emergency'; })], ['Waiting for parts', queue.filter(function (j) { return j.status === 'parts'; })]];
    var h = '<section class="card pad queue" data-queue="1" aria-labelledby="qT"><div class="split"><h2 id="qT">Not planned</h2><span class="hint">' + plural(queue.length, 'job', 'jobs') + '</span></div>';
    if (!queue.length) h += emptyState('check', 'Everything is planned.');
    groups.forEach(function (g) { if (g[1].length) h += '<h3>' + esc(g[0]) + ' · ' + g[1].length + '</h3>' + g[1].map(qItem).join(''); });
    return h + '<p class="hint">Drop a planned card here to take it off the board.</p></section>';
  }
  function phoneBoard(d, techs, jobs, queue) {
    var sj = sel && IX.job[sel] && canPlan(IX.job[sel]) ? IX.job[sel] : null;
    var shown = detailUi.allQueue ? queue : queue.slice(0, 4);
    var h = '<section class="card pad queue" data-queue="1" style="margin-bottom:12px"><div class="split"><h2>Not planned</h2><span class="hint">' + plural(queue.length, 'job', 'jobs') + ', most urgent first</span></div>' + (queue.length ? shown.map(qItem).join('') : emptyState('check', 'Everything is planned.')) +
      (queue.length > 4 ? '<button type="button" class="btn sm" data-act="allqueue">' + (detailUi.allQueue ? 'Show the 4 most urgent' : 'Show all ' + queue.length) + '</button>' : '') + '</section>';
    h += '<div class="pboard">' + techs.map(function (t) {
      var mine = jobs.filter(function (j) { return j.techId === t.id; });
      var rows = E.WINDOWS.map(function (w, i) {
        var starts = mine.filter(function (j) { return E.winIndex(j.window) === i; }), cont = mine.filter(function (j) { var r = E.winRange(j); return r[0] < i && i < r[1]; });
        var inner = starts.map(function (j) { return boardCard(j); }).join('') + cont.map(function (j) { return '<span class="hint">↳ ' + esc(j.no) + ' continues</span>'; }).join('');
        return '<li><span class="w">' + w.label + '</span><div class="stack" style="gap:6px">' + (inner || (sj ? dropBtn(sj, t, d, w.id) : '<span class="freebtn">Free</span>')) + '</div></li>';
      }).join('');
      return '<section class="card ptech tc tc-' + esc(t.colour) + '"><div class="hd">' + techChip(t) + '<span class="hint">' + esc(t.base) + '</span></div><div class="skills" style="margin:-4px 0 8px">' + skillTags(t) + '</div><ul class="pslots">' + rows + '</ul></section>';
    }).join('') + '</div>';
    return h;
  }
  /** the assign sheet: day, technician and window, with the warnings for the current choice */
  function openAssign(j) {
    if (!canPlan(j)) { toast(j.no + ' is ' + E.STATUS[j.status].name.toLowerCase() + ' and cannot be planned.'); return; }
    var c = custOf(j), a = assetOf(j), techs = activeTechs();
    var dayOver = hmLj() >= E.WINDOWS[E.WINDOWS.length - 1].end, firstFree = E.isWorkday(TODAY, HMAP) && !dayOver ? TODAY : E.nextWorkday(TODAY, HMAP);
    var startDay = j.date && j.date >= TODAY ? j.date : route.name === 'board' && boardDate() >= TODAY ? boardDate() : j.preferredDate && j.preferredDate >= TODAY ? j.preferredDate : firstFree;
    if (startDay === TODAY && dayOver) startDay = firstFree;
    var st = { date: startDay, tech: j.techId || '', win: j.window || '' };
    var bookedOf = function (t, d) { var n = 0; dayJobs(d).forEach(function (x) { if (x.techId === t.id && x.id !== j.id) { var r = E.winRange(x); n += r[1] - r[0]; } }); return n; };
    if (!st.tech) {
      var best = techs.map(function (t) { return { t: t, miss: E.missingSkills(t, a.kind, j.type).length, km: E.distanceKm(t.base, c.city), n: bookedOf(t, st.date) }; })
        .sort(function (x, y) { return x.miss - y.miss || (x.n >= 4) - (y.n >= 4) || ((x.km == null ? 99 : x.km) + x.n * 8) - ((y.km == null ? 99 : y.km) + y.n * 8); })[0];
      st.tech = best ? best.t.id : '';
    }
    function freeWin() { for (var w = 0; w < 4; w++) { var id = E.WINDOWS[w].id; if (!E.conflicts(j, { date: st.date, window: id }, conflictCtx(j, st.tech)).some(function (x) { return x.code === 'double' || x.level === 'error' || x.code === 'past'; })) return id; } return E.WINDOWS[0].id; }
    if (!st.win) st.win = freeWin();
    modal({ title: 'Assign ' + j.no, submitLabel: 'Assign',
      body: '<p class="sub">' + esc(c.name + ' · ' + c.city + ' · ' + typeName(j.type) + ' · ' + kindShort(a.kind)) + '</p><div class="badges">' + prBadge(j) + slaBadge(j) + '</div>' +
        '<div class="field"><label for="asDate">Day</label><input type="date" class="in" id="asDate" value="' + esc(st.date) + '"></div>' +
        '<fieldset class="grp"><legend>Technician</legend><div class="pick" id="asTechs"></div></fieldset>' +
        '<fieldset class="grp"><legend>Arrival window' + (E.jobSpan(j) > 1 ? ' (the job takes ' + E.jobSpan(j) + ' windows)' : '') + '</legend><div class="seg" id="asWins" role="group" aria-label="Arrival window"></div></fieldset><div id="asWarn"></div>',
      mount: function (form) {
        function draw(what) {
          var a2 = document.activeElement, keep = a2 && a2.getAttribute ? (a2.getAttribute('data-k') || '') : '';
          if (what !== 'wins') form.querySelector('#asTechs').innerHTML = techs.map(function (t) {
            var miss = E.missingSkills(t, a.kind, j.type), km = E.distanceKm(t.base, c.city), n = bookedOf(t, st.date);
            return '<label><input type="radio" name="asT" value="' + esc(t.id) + '" data-k="t-' + esc(t.id) + '"' + (st.tech === t.id ? ' checked' : '') + '><span>' + esc(t.name) + '<small>' + (miss.length ? 'no ' + esc(miss.join(', ')) + ' skill · ' : '') + (km != null ? km + ' km · ' : '') + n + ' of 4 booked</small></span></label>';
          }).join('');
          form.querySelector('#asWins').innerHTML = E.WINDOWS.map(function (w) {
            var busy = st.tech && E.conflicts(j, { date: st.date, window: w.id }, conflictCtx(j, st.tech)).some(function (x) { return x.code === 'double'; });
            return '<button type="button" data-win="' + w.id + '" data-k="w-' + w.id + '" aria-pressed="' + (st.win === w.id) + '">' + w.label + (busy ? ' · busy' : '') + '</button>';
          }).join('');
          var list = st.tech && E.isDate(st.date) ? E.conflicts(j, { date: st.date, window: st.win }, conflictCtx(j, st.tech)) : [];
          form.querySelector('#asWarn').innerHTML = st.tech ? warnList(list) : '';
          if (keep) { var n2 = form.querySelector('[data-k="' + keep + '"]'); if (n2) n2.focus(); }
        }
        form.addEventListener('change', function (e) {
          if (e.target.name === 'asT') { st.tech = e.target.value; draw('wins'); }
          if (e.target.id === 'asDate' && E.isDate(e.target.value)) { st.date = e.target.value; draw(); }
        });
        form.addEventListener('click', function (e) { var b = e.target.closest('[data-win]'); if (b) { e.preventDefault(); st.win = b.getAttribute('data-win'); draw('wins'); } });
        draw();
      },
      onSubmit: function () {
        if (!st.tech || !st.win || !E.isDate(st.date)) return 'Choose a day, a technician and a window.';
        var errs = E.conflicts(j, { date: st.date, window: st.win }, conflictCtx(j, st.tech)).filter(function (x) { return x.level === 'error'; });
        if (errs.length) return errs[0].text;
        doAssign(j, st.tech, st.date, st.win);
        return null;
      } });
  }

  // ════════════════════════════════════════════════════════════════════════
