  var PERIODS = { '4w': [28, 'Last 4 weeks'], '13w': [91, 'Last 13 weeks'], '9m': [X.HISTORY_DAYS, 'Last 9 months'] };
  function niceStep(span) { var raw = (span || 1) / 4, p = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), m = raw / p; return (m < 1.5 ? 1 : m < 3 ? 2 : m < 7 ? 5 : 10) * p; }
  /** stacked bars; cats [{ label, title }], series [{ name, cls, values }] */
  function barChart(label, cats, series, opts) {
    opts = opts || {};
    var W = opts.w || 720, H = opts.h || 230, L = 52, R = 8, T = 10, B = 28, n = Math.max(1, cats.length), fmt = opts.fmt || function (v) { return nf0.format(v); };
    var tot = cats.map(function (c, i) { return series.reduce(function (s, se) { return s + (se.values[i] || 0); }, 0); });
    var hi = Math.max.apply(null, tot.concat([opts.min || 1])), step = niceStep(hi); hi = Math.ceil(hi / step) * step;
    var x = function (i) { return L + (W - L - R) * i / n; }, y = function (v) { return T + (H - T - B) * (1 - v / hi); }, bw = Math.max(3, (W - L - R) / n * 0.66), every = Math.ceil(n / 13), g = '';
    for (var v = 0; v <= hi + 1e-9; v += step) g += '<line class="grid-l" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '"/><text class="ax" x="' + (L - 6) + '" y="' + (y(v) + 3.5).toFixed(1) + '" text-anchor="end">' + esc(fmt(v)) + '</text>';
    cats.forEach(function (c, i) {
      var acc = 0, cx = (x(i) + x(i + 1)) / 2;
      series.forEach(function (se) {
        var val = se.values[i] || 0; if (!val) return;
        g += '<rect class="' + se.cls + '" x="' + (cx - bw / 2).toFixed(1) + '" y="' + y(acc + val).toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + Math.max(0.5, y(acc) - y(acc + val)).toFixed(1) + '" rx="1.5"><title>' + esc(c.title + ' · ' + se.name + ': ' + fmt(val)) + '</title></rect>';
        acc += val;
      });
      if (i % every === 0) g += '<text class="ax" x="' + cx.toFixed(1) + '" y="' + (H - 9) + '" text-anchor="middle">' + esc(c.label) + '</text>';
    });
    g += '<line class="base" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(0) + '" y2="' + y(0) + '"/>';
    return '<div class="chart"><svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(label) + '">' + g + '</svg></div>' +
      (series.length > 1 ? '<div class="legend">' + series.map(function (se) { return '<span><i class="' + se.cls + '" style="background:currentColor"></i>' + esc(se.name) + '</span>'; }).join('') + '</div>' : '');
  }
