  function fitSheet() {
    var wrap = document.querySelector('.sheetwrap'), sh = $('sheet'); if (!wrap || !sh) return;
    sh.style.transform = ''; sh.style.transformOrigin = ''; wrap.style.height = ''; wrap.style.overflow = '';
    var cs = getComputedStyle(wrap), avail = wrap.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight), w = sh.offsetWidth;
    if (avail > 0 && w > avail + 1) { var k = avail / w; sh.style.transformOrigin = 'top left'; sh.style.transform = 'scale(' + k + ')'; wrap.style.height = Math.ceil(sh.offsetHeight * k + parseFloat(cs.paddingBottom)) + 'px'; wrap.style.overflow = 'hidden'; }
  }
  function partLabel(p, L) { return p ? (L === 'en' ? p.name : p[L] || p.name) : ''; }
  /** the payment block of the report: a UPN QR (Slovenian payers) or an EPC SEPA QR (other EU payers) for what is left
   * to pay, or "Paid on site" when it was paid in full on site. Nothing for jobs without a charge or not done yet. */
  function payBlock(j, p, L, T) {
    var c = custOf(j), pay = E.reportPayment(j, p, { company: db.company, settings: db.settings, country: E.countryOf(c), lang: L, today: TODAY });
    if (!pay) return '';
    var f = function (k, v, cls) { return '<div class="f"><span>' + esc(T(k)) + '</span><b' + (cls ? ' class="' + cls + '"' : '') + '>' + v + '</b></div>'; }, ps = pay.paid;
    var paidLine = ps.paid > 0 ? '<div class="paidbox"><b>' + esc(T('paidOnSite')) + '</b><span>' + esc(T('paidAmount') + ': ' + eur(ps.paid) + ' · ' + T(ps.method === 'cash' ? 'paidCash' : 'paidCard') + (ps.at ? ' · ' + dt(E.dateOf(ps.at)) + ' ' + tm(ps.at) : '')) + '</span></div>' : '';
    if (pay.kind === 'paid') return '<h2>' + esc(T('payTitle')) + '</h2><div class="pay keep">' + paidLine + '</div>';
    var qr = '';
    if (pay.kind === 'upn' || pay.kind === 'epc') {
      try {
        var Q = window.ServiceQR, made = pay.kind === 'upn'
          ? Q.upnQr({ iban: pay.iban, amount: pay.amount, reference: pay.reference, name: pay.name, street: pay.street, city: pay.city, purpose: pay.purpose, purposeCode: pay.purposeCode, dueDate: pay.dueDate })
          : Q.epcQr({ iban: pay.iban, bic: pay.bic, amount: pay.amount, name: pay.name, reference: pay.reference, text: pay.text, purposeCode: pay.purposeCode });
        qr = '<div class="qr">' + Q.svg(made.qr, { title: T(pay.kind === 'upn' ? 'payUpn' : 'payEpc') }) + '<span>' + esc(pay.kind === 'upn' ? 'UPN QR' : 'SEPA QR') + '</span></div>';
      } catch (e) { qr = ''; if (window.console) console.warn('Service jobs: no QR code', e); }
    }
    var head = pay.kind === 'upn' ? T('payUpn') : pay.kind === 'epc' ? T('payEpc') : T('payTitle');
    return '<h2>' + esc(head) + '</h2><div class="pay keep' + (qr ? '' : ' noqr') + '">' + qr + '<div class="pdet">' + paidLine +
      '<div class="g2">' + f(ps.paid > 0 ? 'remaining' : 'toPay', esc(eur(pay.amount)), 'amt') + (pay.dueDate ? f('payBy', esc(dt(pay.dueDate))) : '') +
      f('payee', esc(pay.name) + '<br>' + esc([pay.street, pay.city].filter(Boolean).join(', '))) + f('iban', pay.iban ? esc(E.ibanText(pay.iban)) : '—', 'mono') +
      f('reference', esc(pay.reference), 'mono') + (pay.purpose ? f('purpose', esc(pay.purpose)) : '') + '</div>' +
      '<p class="scan">' + esc(qr ? T('payScan') : T('payNoQr')) + '</p></div></div>';
  }
