  window.addEventListener('beforeprint', fitSheet);

  // ════════════════════════════════════════════════════════════════════════
  // Cloud sync (shared StratumSync library), other tabs, clock, start
  // ════════════════════════════════════════════════════════════════════════
  var SYNC = null;
  function syncChanged() { if (SYNC && !applying) { try { SYNC.changed(); } catch (e) { /* sync unavailable */ } } }
  function usedHashes(d) {
    var used = {};
    (d.jobs || []).forEach(function (j) { (j.photos || []).forEach(function (p) { if (p.hash) used[p.hash] = 1; }); if (j.signature && j.signature.hash) used[j.signature.hash] = 1; });
    return used;
  }
