    try { data = X.unpack(data); } catch (e) { data = null; }
    if (!valid(data)) return Promise.reject(new Error('The cloud copy is not Service jobs data this version can read.'));
    applying = true;
    clearTimeout(saveTimer); saveTimer = null;
    db = data; ensureSchema(); reindex();
